function awaitProviderOperation<T>(work: () => T | PromiseLike<T>, signal?: AbortSignal): Promise<T> {
	if (signal?.aborted) return Promise.reject(signal.reason ?? new Error("Request was aborted"));
	const value = work();
	if (!signal) return Promise.resolve(value);
	if (signal.aborted) {
		void Promise.resolve(value).catch(() => undefined);
		return Promise.reject(signal.reason ?? new Error("Request was aborted"));
	}
	return new Promise<T>((resolve, reject) => {
		const abort = () => {
			signal.removeEventListener("abort", abort);
			reject(signal.reason ?? new Error("Request was aborted"));
		};
		signal.addEventListener("abort", abort, { once: true });
		Promise.resolve(value).then(
			result => { signal.removeEventListener("abort", abort); resolve(result); },
			error => { signal.removeEventListener("abort", abort); reject(error); },
		);
	});
}

